#[ensures(|res: Vec<i32>| forall(|j: usize| j < a.len() ==> res[j] == 1))]
fn ones_like<T>(a: &Vec<T>) -> Vec<i32> {
    let n = a.len();
    let mut result = Vec::with_capacity(n);
    let mut i: usize = 0;

    // Loop from 0 up to n, pushing 1 each iteration
    while i < n {
        // Loop invariants:
        invariant!(i <= n);
        invariant!(result.len() == i);
        invariant!(forall(|j: usize| j < i ==> result[j] == 1));
        // We decrease this measure to show termination
        decreases!(n - i);

        result.push(1);
        i += 1;
    }

    result
}

